/// ap_fixed quantification mode
enum ap_q_mode {
  AP_RND,         //< rounding to plus infinity
  AP_RND_ZERO,    //< rounding to zero
  AP_RND_MIN_INF, //< rounding to minus infinity
  AP_RND_INF,     //< rounding to infinity
  AP_RND_CONV,    //< convergent rounding
  AP_TRN,         //< truncation
  AP_TRN_ZERO,    //< truncation to zero
};
// FIXME for legacy code
/// ap_fixed saturation mode
enum ap_o_mode {
  AP_SAT,      //< saturation
  AP_SAT_ZERO, //< saturation to zero
  AP_SAT_SYM,  //< symmetrical saturation
  AP_WRAP,     //< wrap-around (*)
  AP_WRAP_SM,  //< sign magnitude wrap-around (*)
};
// FIXME for legacy code
template <int _AP_W, bool _AP_S> struct ap_int_base;
template <int _AP_W> struct ap_int;
template <int _AP_W> struct ap_uint;
template <int _AP_W, bool _AP_S> struct ap_range_ref;
template <int _AP_W, bool _AP_S> struct ap_bit_ref;
template <int _AP_W1, typename _AP_T1, int _AP_W2, typename _AP_T2>
struct ap_concat_ref;
template <int _AP_W, int _AP_I, bool _AP_S = true, ap_q_mode _AP_Q = AP_TRN,
          ap_o_mode _AP_O = AP_WRAP, int _AP_N = 0>
struct ap_fixed_base;
template <int _AP_W, int _AP_I, ap_q_mode _AP_Q = AP_TRN,
          ap_o_mode _AP_O = AP_WRAP, int _AP_N = 0>
struct ap_fixed;
template <int _AP_W, int _AP_I, ap_q_mode _AP_Q = AP_TRN,
          ap_o_mode _AP_O = AP_WRAP, int _AP_N = 0>
struct ap_ufixed;
template <int _AP_W, int _AP_I, bool _AP_S, ap_q_mode _AP_Q, ap_o_mode _AP_O,
          int _AP_N>
struct af_range_ref;
template <int _AP_W, int _AP_I, bool _AP_S, ap_q_mode _AP_Q, ap_o_mode _AP_O,
          int _AP_N>
struct af_bit_ref;
/// string base mode
enum BaseMode { AP_BIN = 2, AP_OCT = 8, AP_DEC = 10, AP_HEX = 16 };
// Alias C data types
typedef signed long long ap_slong;
typedef unsigned long long ap_ulong;
enum {
  _AP_SIZE_char = 8,
  _AP_SIZE_short = sizeof(short) * 8,
  _AP_SIZE_int = sizeof(int) * 8,
  _AP_SIZE_long = sizeof(long) * 8,
  _AP_SIZE_ap_slong = sizeof(ap_slong) * 8
};
