    using pointer = _Ptr;
    /// The type pointed to.
    using element_type =
        __detected_or_t<__get_first_arg_t<_Ptr>, __element_type, _Ptr>;
    /// The type used to represent the difference between two pointers.
    using difference_type = __detected_or_t<ptrdiff_t, __difference_type, _Ptr>;
