extern "C" {
/* These are all the characteristics of characters.
   If there get to be more than 16 distinct characteristics,
   many things must be changed that use `unsigned short int's.

   The characteristics are stored always in network byte order (big
   endian).  We define the bit value interpretations here dependent on the
   machine's byte order.  */
enum {
  _ISupper = ((0) < 8 ? ((1 << (0)) << 8) : ((1 << (0)) >> 8)), /* UPPERCASE. */
  _ISlower = ((1) < 8 ? ((1 << (1)) << 8) : ((1 << (1)) >> 8)), /* lowercase. */
  _ISalpha =
      ((2) < 8 ? ((1 << (2)) << 8) : ((1 << (2)) >> 8)), /* Alphabetic.  */
  _ISdigit = ((3) < 8 ? ((1 << (3)) << 8) : ((1 << (3)) >> 8)), /* Numeric.  */
  _ISxdigit = ((4) < 8 ? ((1 << (4)) << 8)
                       : ((1 << (4)) >> 8)), /* Hexadecimal numeric.  */
  _ISspace =
      ((5) < 8 ? ((1 << (5)) << 8) : ((1 << (5)) >> 8)), /* Whitespace.  */
  _ISprint = ((6) < 8 ? ((1 << (6)) << 8) : ((1 << (6)) >> 8)), /* Printing.  */
  _ISgraph = ((7) < 8 ? ((1 << (7)) << 8) : ((1 << (7)) >> 8)), /* Graphical. */
  _ISblank = ((8) < 8 ? ((1 << (8)) << 8)
                      : ((1 << (8)) >> 8)), /* Blank (usually SPC and TAB).  */
  _IScntrl = ((9) < 8 ? ((1 << (9)) << 8)
                      : ((1 << (9)) >> 8)), /* Control character.  */
  _ISpunct =
      ((10) < 8 ? ((1 << (10)) << 8) : ((1 << (10)) >> 8)), /* Punctuation.  */
  _ISalnum =
      ((11) < 8 ? ((1 << (11)) << 8) : ((1 << (11)) >> 8)) /* Alphanumeric.  */
};
/* These are defined in ctype-info.c.
   The declarations here must match those in localeinfo.h.

   In the thread-specific locale model (see `uselocale' in <locale.h>)
   we cannot use global variables for these as was done in the past.
   Instead, the following accessor functions return the address of
   each variable, which is local to the current thread if multithreaded.

   These point into arrays of 384, so they can be indexed by any `unsigned
   char' value [0,255]; by EOF (-1); or by any `signed char' value
   [-128,-1).  ISO C requires that the ctype functions work for `unsigned
   char' values and for EOF; we also support negative `signed char' values
   for broken old programs.  The case conversion arrays are of `int's
   rather than `unsigned char's because tolower (EOF) must be EOF, which
   doesn't fit into an `unsigned char'.  But today more important is that
   the arrays are also used for multi-byte character sets.  */
extern const unsigned short int **__ctype_b_loc(void) throw()
    __attribute__((__const__));
extern const __int32_t **__ctype_tolower_loc(void) throw()
    __attribute__((__const__));
extern const __int32_t **__ctype_toupper_loc(void) throw()
    __attribute__((__const__));
/* The following names are all functions:
     int isCHARACTERISTIC(int c);
   which return nonzero iff C has CHARACTERISTIC.
   For the meaning of the characteristic names, see the `enum' above.  */
extern int isalnum(int) throw();
extern int isalpha(int) throw();
extern int iscntrl(int) throw();
extern int isdigit(int) throw();
extern int islower(int) throw();
extern int isgraph(int) throw();
extern int isprint(int) throw();
extern int ispunct(int) throw();
extern int isspace(int) throw();
extern int isupper(int) throw();
extern int isxdigit(int) throw();
/* Return the lowercase version of C.  */
extern int tolower(int __c) throw();
/* Return the uppercase version of C.  */
extern int toupper(int __c) throw();
/* ISO C99 introduced one new function.  */
extern int isblank(int) throw();
/* Test C for a set of character classes according to MASK.  */
extern int isctype(int __c, int __mask) throw();
/* Return nonzero iff C is in the ASCII set
   (i.e., is no more than 7 bits wide).  */
extern int isascii(int __c) throw();
/* Return the part of C that is in the ASCII set
   (i.e., the low-order 7 bits of C).  */
extern int toascii(int __c) throw();
/* These are the same as `toupper' and `tolower' except that they do not
   check the argument for being in the range of a `char'.  */
extern int _toupper(int) throw();
extern int _tolower(int) throw();
/* This code is needed for the optimized mapping functions.  */
/* POSIX.1-2008 extended locale interface (see locale.h).  */
/* These definitions are similar to the ones above but all functions
   take as an argument a handle for the locale which shall be used.  */
/* The following names are all functions:
     int isCHARACTERISTIC(int c, locale_t *locale);
   which return nonzero iff C has CHARACTERISTIC.
   For the meaning of the characteristic names, see the `enum' above.  */
extern int isalnum_l(int, locale_t) throw();
extern int isalpha_l(int, locale_t) throw();
extern int iscntrl_l(int, locale_t) throw();
extern int isdigit_l(int, locale_t) throw();
extern int islower_l(int, locale_t) throw();
extern int isgraph_l(int, locale_t) throw();
extern int isprint_l(int, locale_t) throw();
extern int ispunct_l(int, locale_t) throw();
extern int isspace_l(int, locale_t) throw();
extern int isupper_l(int, locale_t) throw();
extern int isxdigit_l(int, locale_t) throw();
extern int isblank_l(int, locale_t) throw();
/* Return the lowercase version of C in locale L.  */
extern int __tolower_l(int __c, locale_t __l) throw();
extern int tolower_l(int __c, locale_t __l) throw();
/* Return the uppercase version of C.  */
extern int __toupper_l(int __c, locale_t __l) throw();
extern int toupper_l(int __c, locale_t __l) throw();
}
