// Define ssdm_int and _ssdm_op.
static inline unsigned char guess_radix(const char *s) {
  unsigned char rd = 10; ///< default radix
  const char *p = s;
  // skip neg sign if it exists
  if (p[0] == '-' || p[0] == '+')
    ++p;
  // guess based on following two bits.
  if (p[0] == '0') {
    if (p[1] == 'b' || p[1] == 'B') {
      rd = 2;
    } else if (p[1] == 'o' || p[1] == 'O') {
      rd = 8;
    } else if (p[1] == 'x' || p[1] == 'X') {
      rd = 16;
    } else if (p[1] == 'd' || p[1] == 'D') {
      rd = 10;
    }
  }
  return rd;
}
