  __gmp_asize = __gmp_a->_mp_size;
  __gmp_result = (__gmp_asize >= 0); /* zero is a square, negatives are not */
  if (__builtin_expect((__gmp_asize > 0) != 0, 1))
    __gmp_result = __gmpn_perfect_square_p(__gmp_a->_mp_d, __gmp_asize);
  return __gmp_result;
