inline half scalbln(half arg, long exp) {
  long e = arg.get_bits() & 0x7C00;
  if (e == 0x7C00)
    return arg;
  unsigned int m = arg.get_bits() & 0x3FF;
  if (e >>= 10)
    m |= 0x400;
  else {
    if (!m)
      return arg;
    for (m <<= 1; m < 0x400; m <<= 1, --e)
      ;
  }
  e += exp;
  half::uint16 value = arg.get_bits() & 0x8000;
  if (e > 30) {
    value |= 0x7C00;
  } else if (e > 0)
    value |= (e << 10) | (m & 0x3FF);
  else if (e > -11) {
    //	if(half::round_style == std::round_to_nearest)
    {
      m += 1 << -e;
      m -= (m >> (1 - e)) & 1;
    }
    value |= m >> (1 - e);
  }
  half t;
  t.set_bits(value);
  return t;
}
inline half ldexp(half arg, int exp) { return scalbln(arg, exp); }
inline half ldexp(float arg, int exp) { return scalbln(arg, exp); }
