        char __format;
        char __mod = 0;
        const char __c = __ctype.narrow(*__beg, 0);
        if (__c != 'E' && __c != 'O')
          __format = __c;
        else if (++__beg != __end) {
          __mod = __c;
          __format = __ctype.narrow(*__beg, 0);
        } else
          break;
        __s = this->do_put(__s, __io, __fill, __tm, __format, __mod);
