  // DEBUG(cerr << "KnuthDiv: m=" << m << " n=" << n << '\n');
  // DEBUG(cerr << "KnuthDiv: original:");
  // DEBUG(for (int i = m+n; i >=0; i--) cerr << " " << std::setbase(16) <<
  // u[i]);
  // DEBUG(cerr << " by");
  // DEBUG(for (int i = n; i >0; i--) cerr << " " << std::setbase(16) <<
  // v[i-1]);
