public:
  inline void fromString(const char *strStart, uint32_t slen, uint8_t radix) {
    bool isNeg = strStart[0] == '-';
    if (isNeg) {
      strStart++;
      slen--;
    }
    if (strStart[0] == '0' && (strStart[1] == 'b' || strStart[1] == 'B')) {
      // if(radix == 0) radix = 2;
      do {
        if ((radix != 2)) {
          fprintf(stderr,
                  "WARNING: "
                  "%s seems to have base %d, but %d given.",
                  strStart, 2, radix);
          fprintf(stderr, "\n");
        }
      } while (0);
      strStart += 2;
      slen -= 2;
    } else if (strStart[0] == '0' &&
               (strStart[1] == 'o' || strStart[1] == 'O')) {
      // if (radix == 0) radix = 8;
      do {
        if ((radix != 8)) {
          fprintf(stderr,
                  "WARNING: "
                  "%s seems to have base %d, but %d given.",
                  strStart, 8, radix);
          fprintf(stderr, "\n");
        }
      } while (0);
      strStart += 2;
      slen -= 2;
    } else if (strStart[0] == '0' &&
               (strStart[1] == 'x' || strStart[1] == 'X')) {
      // if (radix == 0) radix = 16;
      do {
        if ((radix != 16)) {
          fprintf(stderr,
                  "WARNING: "
                  "%s seems to have base %d, but %d given.",
                  strStart, 16, radix);
          fprintf(stderr, "\n");
        }
      } while (0);
      strStart += 2;
      slen -= 2;
    } else if (strStart[0] == '0' &&
               (strStart[1] == 'd' || strStart[1] == 'D')) {
      // if (radix == 0) radix = 10;
      do {
        if ((radix != 10)) {
          fprintf(stderr,
                  "WARNING: "
                  "%s seems to have base %d, but %d given.",
                  strStart, 10, radix);
          fprintf(stderr, "\n");
        }
      } while (0);
      strStart += 2;
      slen -= 2;
    } else if (radix == 0) {
      // radix = 2; // XXX default value
    }
    // Check our assumptions here
    (static_cast<bool>(
         (radix == 10 || radix == 8 || radix == 16 || radix == 2) &&
         "Radix should be 2, 8, 10, or 16!")
         ? void(0)
         : __assert_fail("(radix == 10 || radix == 8 || radix == 16 || radix "
                         "== 2) && \"Radix should be 2, 8, 10, or 16!\"",
                         "/afs/ece.cmu.edu/class/ece643/software/xilinxVitis//"
                         "Vitis_HLS/2023.2/include/etc/ap_private.h",
                         1583, __extension__ __PRETTY_FUNCTION__));
    (static_cast<bool>(strStart && "String is null?")
         ? void(0)
         : __assert_fail("strStart && \"String is null?\"",
                         "/afs/ece.cmu.edu/class/ece643/software/xilinxVitis//"
                         "Vitis_HLS/2023.2/include/etc/ap_private.h",
                         1584, __extension__ __PRETTY_FUNCTION__));
    // Clear bits.
    uint64_t tmpVAL = VAL = 0;
    switch (radix) {
    case 2:
      //        sscanf(strStart,"%b",&VAL);
      // tmpVAL = *strStart =='1' ? ~0ULL : 0;
      for (; *strStart; ++strStart) {
        (static_cast<bool>((*strStart == '0' || *strStart == '1') &&
                           ("Wrong binary number"))
             ? void(0)
             : __assert_fail(
                   "(*strStart == '0' || *strStart == '1') && (\"Wrong binary "
                   "number\")",
                   "/afs/ece.cmu.edu/class/ece643/software/xilinxVitis//"
                   "Vitis_HLS/2023.2/include/etc/ap_private.h",
                   1595, __extension__ __PRETTY_FUNCTION__));
        tmpVAL <<= 1;
        tmpVAL |= (*strStart - '0');
      }
      break;
    case 8:
      sscanf(strStart, "%lo", &tmpVAL);
      break;
    case 10:
      sscanf(strStart, "%lu", &tmpVAL);
      break;
    case 16:
      sscanf(strStart, "%lx", &tmpVAL);
      break;
    default:
      (static_cast<bool>(true && "Unknown radix")
           ? void(0)
           : __assert_fail("true && \"Unknown radix\"",
                           "/afs/ece.cmu.edu/class/ece643/software/xilinxVitis/"
                           "/Vitis_HLS/2023.2/include/etc/ap_private.h",
                           1634, __extension__ __PRETTY_FUNCTION__));
      // error
    }
    VAL = isNeg ? (ValType)(-tmpVAL) : (ValType)(tmpVAL);
    clearUnusedBits();
  }

