  /// Comparisons
  //-----------------------------------------------------------------
  template <int _AP_W1, bool _AP_S1>
  inline bool operator==(const ap_private<_AP_W1, _AP_S1> &op) const {
    ap_private<_AP_W, _AP_S> tmp(*this);
    tmp.clearUnusedBits();
    ap_private<_AP_W1, _AP_S1> op_(op);
    op_.clearUnusedBits();
    enum {
      _AP_MAX_W = ((((_AP_W) > (_AP_W1) ? (_AP_W) : (_AP_W1))) > (32)
                       ? (((_AP_W) > (_AP_W1) ? (_AP_W) : (_AP_W1)))
                       : (32))
    };
    ap_private<_AP_MAX_W, false> lhs(tmp);
    ap_private<_AP_MAX_W, false> rhs(op_);
    if (_AP_MAX_W <= 64) {
      return (uint64_t)lhs.get_VAL() == (uint64_t)rhs.get_VAL();
    } else
      return lhs == rhs;
  }
  template <int _AP_W2, bool _AP_S2>
  inline bool operator!=(const ap_private<_AP_W2, _AP_S2> &op) const {
    return !(*this == op);
  }
  template <int _AP_W2, bool _AP_S2>
  inline bool operator>(const ap_private<_AP_W2, _AP_S2> &op) const {
    ap_private<_AP_W, _AP_S> tmp(*this);
    tmp.clearUnusedBits();
    ap_private<_AP_W2, _AP_S2> op_(op);
    op_.clearUnusedBits();
    enum {
      _AP_MAX_W = ((_AP_W + (_AP_S || _AP_S2)) > (_AP_W2 + (_AP_S || _AP_S2))
                       ? (_AP_W + (_AP_S || _AP_S2))
                       : (_AP_W2 + (_AP_S || _AP_S2)))
    };
    ap_private<_AP_MAX_W, _AP_S> lhs(tmp);
    ap_private<_AP_MAX_W, _AP_S2> rhs(op_);
    // this will follow gcc rule for comparison
    // between different bitwidth and signness
    if (_AP_S == _AP_S2)
      return _AP_S ? lhs.sgt(rhs) : lhs.ugt(rhs);
    else if (_AP_W < 32 && _AP_W2 < 32)
      // different signness but both bitwidth is less than 32
      return lhs.sgt(rhs);
    else
      // different signness but bigger bitwidth
      // is greater or equal to 32
      if (_AP_S)
        if (_AP_W2 >= _AP_W)
          return lhs.ugt(rhs);
        else
          return lhs.sgt(rhs);
      else if (_AP_W >= _AP_W2)
        return lhs.ugt(rhs);
      else
        return lhs.sgt(rhs);
  }
  template <int _AP_W2, bool _AP_S2>
  inline bool operator<=(const ap_private<_AP_W2, _AP_S2> &op) const {
    return !(*this > op);
  }
  template <int _AP_W2, bool _AP_S2>
  inline bool operator<(const ap_private<_AP_W2, _AP_S2> &op) const {
    ap_private<_AP_W, _AP_S> tmp(*this);
    tmp.clearUnusedBits();
    ap_private<_AP_W2, _AP_S2> op_(op);
    op_.clearUnusedBits();
    enum {
      _AP_MAX_W = ((_AP_W + (_AP_S || _AP_S2)) > (_AP_W2 + (_AP_S || _AP_S2))
                       ? (_AP_W + (_AP_S || _AP_S2))
                       : (_AP_W2 + (_AP_S || _AP_S2)))
    };
    ap_private<_AP_MAX_W, _AP_S> lhs(tmp);
    ap_private<_AP_MAX_W, _AP_S2> rhs(op_);
    if (_AP_S == _AP_S2)
      return _AP_S ? lhs.slt(rhs) : lhs.ult(rhs);
    else if (_AP_W < 32 && _AP_W2 < 32)
      return lhs.slt(rhs);
    else if (_AP_S)
      if (_AP_W2 >= _AP_W)
        return lhs.ult(rhs);
      else
        return lhs.slt(rhs);
    else if (_AP_W >= _AP_W2)
      return lhs.ult(rhs);
    else
      return lhs.slt(rhs);
  }
  template <int _AP_W2, bool _AP_S2>
  inline bool operator>=(const ap_private<_AP_W2, _AP_S2> &op) const {
    return !(*this < op);
  }
