  template <int _AP_W2, bool _AP_S2>
  inline ap_private &operator%=(const ap_private<_AP_W2, _AP_S2> &op) {
    *this = operator%(op);
    return *this;
  }
  template <int _AP_W1, bool _AP_S1>
  inline typename RType<_AP_W1, _AP_S1>::logic
  operator|(const ap_private<_AP_W1, _AP_S1> &RHS) const {
    enum {
      numWords = (RType<_AP_W1, _AP_S1>::logic_w + APINT_BITS_PER_WORD - 1) /
                 APINT_BITS_PER_WORD
    };
    typename RType<_AP_W1, _AP_S1>::logic Result(0);
    uint32_t i = 0;
    const int _AP_N1 = ap_private<_AP_W1, _AP_S1>::_AP_N;
    uint32_t min_N = std::min((int)_AP_N, _AP_N1);
    uint32_t max_N = std::max((int)_AP_N, _AP_N1);
    for (i = 0; i < min_N; ++i)
      Result.set_pVal(i, pVal[i] | RHS.get_pVal(i));
    if (numWords > i) {
      uint64_t ext = ((_AP_N < _AP_N1 && isNegative()) ||
                      (_AP_N1 < _AP_N && RHS.isNegative()))
                         ? ~0ULL
                         : 0;
      if (_AP_N > _AP_N1)
        for (; i < max_N; i++)
          Result.set_pVal(i, pVal[i] | ext);
      else
        for (; i < max_N; i++)
          Result.set_pVal(i, RHS.get_pVal(i) | ext);
      if (numWords > i) {
        uint64_t ext2 = ((_AP_N > _AP_N1 && isNegative()) ||
                         (_AP_N1 > _AP_N && RHS.isNegative()))
                            ? ~0ULL
                            : 0;
        Result.set_pVal(i, ext | ext2);
      }
    }
    Result.clearUnusedBits();
    return Result;
  };
