template <typename PTR_TYPE, int _AP_W, bool _AP_S>
inline PTR_TYPE *operator+(PTR_TYPE *i_op, const ap_private<_AP_W, _AP_S> &op) {
  typename ap_private<_AP_W, _AP_S>::ValType op2 = op;
  return i_op + op2;
}
