inline typename ap_int_base<_AP_W, _AP_S>::template RType<_AP_W2, _AP_S2>::mult
operator*(const ap_int_base<_AP_W, _AP_S> &op,
          const ap_int_base<_AP_W2, _AP_S2> &op2) {
  typename ap_int_base<_AP_W, _AP_S>::template RType<_AP_W2, _AP_S2>::mult_base
      lhs(op);
  typename ap_int_base<_AP_W, _AP_S>::template RType<_AP_W2, _AP_S2>::mult_base
      rhs(op2);
  typename ap_int_base<_AP_W, _AP_S>::template RType<_AP_W2, _AP_S2>::mult_base
      ret(0);
  ret.V = lhs.V * rhs.V;
  return ret;
}
