/* ap_concat_ref with ap_concat_ref.
 *  ------------------------------------------------------------
 */
//************************************************************************
//  Implement
//      ap_int_base<M+N> = ap_concat_ref<M> OP ap_concat_ref<N>
//  for operators  +, -, *, /, %, >>, <<, &, |, ^
//  Without these operators the operands are converted to int64 and
//  larger results lose informations (higher order bits).
//
//                       operand OP
//                      /          |
//              left-concat         right-concat
//                /     |            /         |
//         <LW1,LT1>  <LW2,LT2>   <RW1,RT1>    <RW2,RT2>
//
//      _AP_LW1, _AP_LT1 (width and type of left-concat's left side)
//      _AP_LW2, _AP_LT2 (width and type of left-concat's right side)
//  Similarly for RHS of operand OP: _AP_RW1, AP_RW2, _AP_RT1, _AP_RT2
//
//  In Verilog 2001 result of concatenation is always unsigned even
//  when both sides are signed.
//************************************************************************
template <int _AP_LW1, typename _AP_LT1, int _AP_LW2, typename _AP_LT2,
          int _AP_RW1, typename _AP_RT1, int _AP_RW2, typename _AP_RT2>
inline
    typename ap_int_base<_AP_LW1 + _AP_LW2,
                         false>::template RType<_AP_RW1 + _AP_RW2, false>::plus
    operator+(const ap_concat_ref<_AP_LW1, _AP_LT1, _AP_LW2, _AP_LT2> &lhs,
              const ap_concat_ref<_AP_RW1, _AP_RT1, _AP_RW2, _AP_RT2> &rhs) {
  return lhs.get() + rhs.get();
}
template <int _AP_LW1, typename _AP_LT1, int _AP_LW2, typename _AP_LT2,
          int _AP_RW1, typename _AP_RT1, int _AP_RW2, typename _AP_RT2>
inline
    typename ap_int_base<_AP_LW1 + _AP_LW2,
                         false>::template RType<_AP_RW1 + _AP_RW2, false>::minus
    operator-(const ap_concat_ref<_AP_LW1, _AP_LT1, _AP_LW2, _AP_LT2> &lhs,
              const ap_concat_ref<_AP_RW1, _AP_RT1, _AP_RW2, _AP_RT2> &rhs) {
  return lhs.get() - rhs.get();
}
template <int _AP_LW1, typename _AP_LT1, int _AP_LW2, typename _AP_LT2,
          int _AP_RW1, typename _AP_RT1, int _AP_RW2, typename _AP_RT2>
inline
    typename ap_int_base<_AP_LW1 + _AP_LW2,
                         false>::template RType<_AP_RW1 + _AP_RW2, false>::mult
    operator*(const ap_concat_ref<_AP_LW1, _AP_LT1, _AP_LW2, _AP_LT2> &lhs,
              const ap_concat_ref<_AP_RW1, _AP_RT1, _AP_RW2, _AP_RT2> &rhs) {
  return lhs.get() * rhs.get();
}
template <int _AP_LW1, typename _AP_LT1, int _AP_LW2, typename _AP_LT2,
          int _AP_RW1, typename _AP_RT1, int _AP_RW2, typename _AP_RT2>
inline
    typename ap_int_base<_AP_LW1 + _AP_LW2,
                         false>::template RType<_AP_RW1 + _AP_RW2, false>::div
    operator/(const ap_concat_ref<_AP_LW1, _AP_LT1, _AP_LW2, _AP_LT2> &lhs,
              const ap_concat_ref<_AP_RW1, _AP_RT1, _AP_RW2, _AP_RT2> &rhs) {
  return lhs.get() / rhs.get();
}
template <int _AP_LW1, typename _AP_LT1, int _AP_LW2, typename _AP_LT2,
          int _AP_RW1, typename _AP_RT1, int _AP_RW2, typename _AP_RT2>
inline
    typename ap_int_base<_AP_LW1 + _AP_LW2,
                         false>::template RType<_AP_RW1 + _AP_RW2, false>::mod
    operator%(const ap_concat_ref<_AP_LW1, _AP_LT1, _AP_LW2, _AP_LT2> &lhs,
              const ap_concat_ref<_AP_RW1, _AP_RT1, _AP_RW2, _AP_RT2> &rhs) {
  return lhs.get() % rhs.get();
}
template <int _AP_LW1, typename _AP_LT1, int _AP_LW2, typename _AP_LT2,
          int _AP_RW1, typename _AP_RT1, int _AP_RW2, typename _AP_RT2>
inline
    typename ap_int_base<_AP_LW1 + _AP_LW2,
                         false>::template RType<_AP_RW1 + _AP_RW2, false>::logic
    operator&(const ap_concat_ref<_AP_LW1, _AP_LT1, _AP_LW2, _AP_LT2> &lhs,
              const ap_concat_ref<_AP_RW1, _AP_RT1, _AP_RW2, _AP_RT2> &rhs) {
  return lhs.get() & rhs.get();
}
template <int _AP_LW1, typename _AP_LT1, int _AP_LW2, typename _AP_LT2,
          int _AP_RW1, typename _AP_RT1, int _AP_RW2, typename _AP_RT2>
inline
    typename ap_int_base<_AP_LW1 + _AP_LW2,
                         false>::template RType<_AP_RW1 + _AP_RW2, false>::logic
    operator|(const ap_concat_ref<_AP_LW1, _AP_LT1, _AP_LW2, _AP_LT2> &lhs,
              const ap_concat_ref<_AP_RW1, _AP_RT1, _AP_RW2, _AP_RT2> &rhs) {
  return lhs.get() | rhs.get();
}
template <int _AP_LW1, typename _AP_LT1, int _AP_LW2, typename _AP_LT2,
          int _AP_RW1, typename _AP_RT1, int _AP_RW2, typename _AP_RT2>
inline
    typename ap_int_base<_AP_LW1 + _AP_LW2,
                         false>::template RType<_AP_RW1 + _AP_RW2, false>::logic
    operator^(const ap_concat_ref<_AP_LW1, _AP_LT1, _AP_LW2, _AP_LT2> &lhs,
              const ap_concat_ref<_AP_RW1, _AP_RT1, _AP_RW2, _AP_RT2> &rhs) {
  return lhs.get() ^ rhs.get();
}
template <int _AP_LW1, typename _AP_LT1, int _AP_LW2, typename _AP_LT2,
          int _AP_RW1, typename _AP_RT1, int _AP_RW2, typename _AP_RT2>
inline
    typename ap_int_base<_AP_LW1 + _AP_LW2,
                         false>::template RType<_AP_RW1 + _AP_RW2, false>::arg1
    operator>>(const ap_concat_ref<_AP_LW1, _AP_LT1, _AP_LW2, _AP_LT2> &lhs,
               const ap_concat_ref<_AP_RW1, _AP_RT1, _AP_RW2, _AP_RT2> &rhs) {
  return lhs.get() >> rhs.get();
}
template <int _AP_LW1, typename _AP_LT1, int _AP_LW2, typename _AP_LT2,
          int _AP_RW1, typename _AP_RT1, int _AP_RW2, typename _AP_RT2>
inline
    typename ap_int_base<_AP_LW1 + _AP_LW2,
                         false>::template RType<_AP_RW1 + _AP_RW2, false>::arg1
    operator<<(const ap_concat_ref<_AP_LW1, _AP_LT1, _AP_LW2, _AP_LT2> &lhs,
               const ap_concat_ref<_AP_RW1, _AP_RT1, _AP_RW2, _AP_RT2> &rhs) {
  return lhs.get() << rhs.get();
}
template <int _AP_W, bool _AP_S>
inline ap_int_base<_AP_W + 1, false>
operator,(const ap_int_base<_AP_W, _AP_S> &op1, bool op2) {
  ap_int_base<1 + _AP_W, false> val(op2);
  ap_int_base<1 + _AP_W, false> ret(op1);
  ret <<= 1;
  if (false) {
    val <<= _AP_W;
    val >>= _AP_W;
  }
  ret |= val;
  return ret;
}
template <int _AP_W, bool _AP_S>
inline ap_int_base<_AP_W + 1, false>
operator,(bool op1, const ap_int_base<_AP_W, _AP_S> &op2) {
  ap_int_base<1 + _AP_W, false> val(op1);
  ap_int_base<1 + _AP_W, false> ret(op2);
  if (_AP_S) {
    ret <<= 1;
    ret >>= 1;
  }
  ret |= val << _AP_W;
  return ret;
}
template <int _AP_W, bool _AP_S>
inline ap_int_base<_AP_W + 1, false>
operator,(const ap_range_ref<_AP_W, _AP_S> &op1, bool op2) {
  ap_int_base<1 + _AP_W, false> val(op2);
  ap_int_base<1 + _AP_W, false> ret(op1);
  ret <<= 1;
  if (false) {
    val <<= _AP_W;
    val >>= _AP_W;
  }
  ret |= val;
  return ret;
}
template <int _AP_W, bool _AP_S>
inline ap_int_base<_AP_W + 1, false>
operator,(bool op1, const ap_range_ref<_AP_W, _AP_S> &op2) {
  ap_int_base<1 + _AP_W, false> val(op1);
  ap_int_base<1 + _AP_W, false> ret(op2);
  int len = op2.length();
  val <<= len;
  ret |= val;
  return ret;
}
template <int _AP_W, bool _AP_S>
inline ap_int_base<1 + 1, false> operator,(const ap_bit_ref<_AP_W, _AP_S> &op1,
                                           bool op2) {
  ap_int_base<1 + 1, false> val(op2);
  val[1] = op1;
  return val;
}
