  inline ap_fixed_base(const char *s, signed char rd = 0) {
    (static_cast<bool>((0 != s) &&
                       ("ap_fixed<> is being initialized with a NULL pointer "
                        "which is not a valid C string"))
         ? void(0)
         : __assert_fail("(0 != s) && (\"ap_fixed<> is being initialized with "
                         "a NULL pointer which is not a valid C string\")",
                         "/afs/ece.cmu.edu/class/ece643/software/xilinxVitis//"
                         "Vitis_HLS/2023.2/include/etc/ap_fixed_base.h",
                         441, __extension__ __PRETTY_FUNCTION__));
    unsigned char radix = rd;
    std::string str =
        ap_private_ops::parseString(s, radix); // will guess rd, default 10
    do {
      if ((str.empty())) {
        fprintf(stderr,
                "WARNING: "
                "ap_fixed<> is being initialized with an empty C string, which "
                "can result in undefined behavior during simulation/synthesis");
        fprintf(stderr, "\n");
      }
    } while (0);
    do {
      if ((radix == 0)) {
        fprintf(stderr,
                "ERROR: "
                "ap_fixed_base(const char* \"%s\", %d), str=%s, radix = %d",
                s, rd, str.c_str(), radix);
        fprintf(stderr, "\n");
        abort();
      }
    } while (0); // TODO remove this check
    fromString(str, radix);
  }
