  // Arithmetic : Binary
  // -------------------------------------------------------------------------
  template <int _AP_W2, int _AP_I2, bool _AP_S2, ap_q_mode _AP_Q2,
            ap_o_mode _AP_O2, int _AP_N2>
  inline typename RType<_AP_W2, _AP_I2, _AP_S2>::mult operator*(
      const ap_fixed_base<_AP_W2, _AP_I2, _AP_S2, _AP_Q2, _AP_O2, _AP_N2> &op2)
      const {
    typename RType<_AP_W2, _AP_I2, _AP_S2>::mult_base r(0), t(0);
    r.V = Base::V;
    t.V = op2.V;
    r.V *= op2.V;
    return r;
  }
  // multiply function deleted.
  template <int _AP_W2, int _AP_I2, bool _AP_S2, ap_q_mode _AP_Q2,
            ap_o_mode _AP_O2, int _AP_N2>
  inline typename RType<_AP_W2, _AP_I2, _AP_S2>::div operator/(
      const ap_fixed_base<_AP_W2, _AP_I2, _AP_S2, _AP_Q2, _AP_O2, _AP_N2> &op2)
      const {
    typename RType<_AP_W2, _AP_I2, _AP_S2>::div_base r;
    enum {
      F2 = _AP_W2 - _AP_I2,
      _W1 =
          ((_AP_W + ((F2) > (0) ? (F2) : (0)) + ((_AP_S2 && !_AP_S) ? 1 : 0)) >
                   (_AP_W2 + ((_AP_S && !_AP_S2) ? 1 : 0))
               ? (_AP_W + ((F2) > (0) ? (F2) : (0)) +
                  ((_AP_S2 && !_AP_S) ? 1 : 0))
               : (_AP_W2 + ((_AP_S && !_AP_S2) ? 1 : 0)))
    };
    ap_int_base<_W1, _AP_S || _AP_S2> dividend, divisior;
    ap_int_base<_W1, _AP_S> tmp1;
    ap_int_base<_W1, _AP_S2> tmp2;
    tmp1.V = Base::V;
    tmp1.V <<= ((F2) > (0) ? (F2) : (0));
    tmp2.V = op2.V;
    dividend = tmp1;
    divisior = tmp2;
    r.V = ((_AP_S || _AP_S2) ? dividend.V.sdiv(divisior.V)
                             : dividend.V.udiv(divisior.V));
    /*
        enum {
          F2 = _AP_W2 - _AP_I2,
          shl = AP_MAX(F2, 0) + AP_MAX(_AP_I2, 0),
    #ifndef __SC_COMPATIBLE__
          shr = AP_MAX(_AP_I2, 0),
    #else
          shr = 0,
    #endif
          W3 = _AP_S2 + _AP_W + shl,
          S3 = _AP_S || _AP_S2,
        };
        ap_int_base<W3, S3> dividend, t;
        dividend.V = Base::V;
        // multiply both by (1 << F2), and than do integer division.
        dividend.V <<= (int) shl;
    #ifdef __SYNTHESIS__
        // .V's have right signedness, and will have right extending.
        t.V = dividend.V / op2.V;
    #else
        // XXX op2 may be wider than dividend, and sdiv and udiv takes the same
    with
        // as left hand operand, so data might be truncated by mistake if not
        // handled here.
        t.V = S3 ? dividend.V.sdiv(op2.V) : dividend.V.udiv(op2.V);
    #endif
        r.V = t.V >> (int) shr;
    */
    return r;
  }
  template <int _AP_W2, int _AP_I2, bool _AP_S2, ap_q_mode _AP_Q2,
            ap_o_mode _AP_O2, int _AP_N2>
  inline typename RType<_AP_W2, _AP_I2, _AP_S2>::plus operator+(
      const ap_fixed_base<_AP_W2, _AP_I2, _AP_S2, _AP_Q2, _AP_O2, _AP_N2> &op2)
      const {
    typename RType<_AP_W2, _AP_I2, _AP_S2>::plus_base ret(0), lhs(*this),
        rhs(op2);
    ret.V = lhs.V + rhs.V;
    return ret;
  }
