  // Comparisons.
  // -------------------------------------------------------------------------
  template <int _AP_W2, int _AP_I2, bool _AP_S2, ap_q_mode _AP_Q2,
            ap_o_mode _AP_O2, int _AP_N2>
  inline bool operator>(const ap_fixed_base<_AP_W2, _AP_I2, _AP_S2, _AP_Q2,
                                            _AP_O2, _AP_N2> &op2) const {
    enum { _AP_F = _AP_W - _AP_I, F2 = _AP_W2 - _AP_I2 };
    if (_AP_F == F2)
      return Base::V > op2.V;
    else if (_AP_F > F2)
      return Base::V >
             ap_fixed_base<((_AP_W2 + _AP_F - F2) > (1) ? (_AP_W2 + _AP_F - F2)
                                                        : (1)),
                           _AP_I2, _AP_S2, _AP_Q2, _AP_O2, _AP_N2>(op2)
                 .V;
    else
      return ap_fixed_base<((_AP_W + F2 - _AP_F + 1) > (1)
                                ? (_AP_W + F2 - _AP_F + 1)
                                : (1)),
                           _AP_I + 1, _AP_S, _AP_Q, _AP_O, _AP_N>(*this)
                 .V > op2.V;
    return false;
  }
  template <int _AP_W2, int _AP_I2, bool _AP_S2, ap_q_mode _AP_Q2,
            ap_o_mode _AP_O2, int _AP_N2>
  inline bool operator<(const ap_fixed_base<_AP_W2, _AP_I2, _AP_S2, _AP_Q2,
                                            _AP_O2, _AP_N2> &op2) const {
    enum { _AP_F = _AP_W - _AP_I, F2 = _AP_W2 - _AP_I2 };
    if (_AP_F == F2)
      return Base::V < op2.V;
    else if (_AP_F > F2)
      return Base::V <
             ap_fixed_base<((_AP_W2 + _AP_F - F2) > (1) ? (_AP_W2 + _AP_F - F2)
                                                        : (1)),
                           _AP_I2, _AP_S2, _AP_Q2, _AP_O2, _AP_N2>(op2)
                 .V;
    else
      return ap_fixed_base<((_AP_W + F2 - _AP_F + 1) > (1)
                                ? (_AP_W + F2 - _AP_F + 1)
                                : (1)),
                           _AP_I + 1, _AP_S, _AP_Q, _AP_O, _AP_N>(*this)
                 .V < op2.V;
    return false;
  }
  template <int _AP_W2, int _AP_I2, bool _AP_S2, ap_q_mode _AP_Q2,
            ap_o_mode _AP_O2, int _AP_N2>
  inline bool operator>=(const ap_fixed_base<_AP_W2, _AP_I2, _AP_S2, _AP_Q2,
                                             _AP_O2, _AP_N2> &op2) const {
    enum { _AP_F = _AP_W - _AP_I, F2 = _AP_W2 - _AP_I2 };
    if (_AP_F == F2)
      return Base::V >= op2.V;
    else if (_AP_F > F2)
      return Base::V >=
             ap_fixed_base<((_AP_W2 + _AP_F - F2) > (1) ? (_AP_W2 + _AP_F - F2)
                                                        : (1)),
                           _AP_I2, _AP_S2, _AP_Q2, _AP_O2, _AP_N2>(op2)
                 .V;
    else
      return ap_fixed_base<((_AP_W + F2 - _AP_F + 1) > (1)
                                ? (_AP_W + F2 - _AP_F + 1)
                                : (1)),
                           _AP_I + 1, _AP_S, _AP_Q, _AP_O, _AP_N>(*this)
                 .V >= op2.V;
    return false;
  }
