  // Bit and Slice Select
  inline af_bit_ref<_AP_W, _AP_I, _AP_S, _AP_Q, _AP_O, _AP_N>
  operator[](unsigned index) {
    do {
      if ((index >= _AP_W)) {
        fprintf(stderr, "WARNING: "
                        "Attempting to read bit beyond MSB");
        fprintf(stderr, "\n");
      }
    } while (0);
    return af_bit_ref<_AP_W, _AP_I, _AP_S, _AP_Q, _AP_O, _AP_N>(this, index);
  }
  template <int _AP_W2, bool _AP_S2>
  inline af_bit_ref<_AP_W, _AP_I, _AP_S, _AP_Q, _AP_O, _AP_N>
  operator[](const ap_int_base<_AP_W2, _AP_S2> &index) {
    do {
      if ((index < 0)) {
        fprintf(stderr, "WARNING: "
                        "Attempting to read bit with negative index");
        fprintf(stderr, "\n");
      }
    } while (0);
    do {
      if ((index >= _AP_W)) {
        fprintf(stderr, "WARNING: "
                        "Attempting to read bit beyond MSB");
        fprintf(stderr, "\n");
      }
    } while (0);
    return af_bit_ref<_AP_W, _AP_I, _AP_S, _AP_Q, _AP_O, _AP_N>(this,
                                                                index.to_int());
  }
  inline bool operator[](unsigned index) const {
    do {
      if ((index >= _AP_W)) {
        fprintf(stderr, "WARNING: "
                        "Attempting to read bit beyond MSB");
        fprintf(stderr, "\n");
      }
    } while (0);
    return (const_cast<ap_fixed_base *>(this)->V).get_bit((index));
  }
