    template <typename _InputIterator>
    _Hashtable(_InputIterator __first, _InputIterator __last,
               size_type __bucket_hint, const _H1 &, const _H2 &, const _Hash &,
               const _Equal &, const _ExtractKey &, const allocator_type &);
