    // Insert a node at the beginning of a bucket.
    void _M_insert_bucket_begin(size_type, __node_type *);
    // Remove the bucket first node
    void _M_remove_bucket_begin(size_type __bkt, __node_type *__next_n,
                                size_type __next_bkt);
    // Get the node before __n in the bucket __bkt
    __node_base *_M_get_previous_node(size_type __bkt, __node_base *__n);
    // Insert node with hash code __code, in bucket bkt if no rehash (assumes
    // no element with its key already present). Take ownership of the node,
    // deallocate it on exception.
    iterator _M_insert_unique_node(size_type __bkt, __hash_code __code,
                                   __node_type *__n, size_type __n_elt = 1);
    // Insert node with hash code __code. Take ownership of the node,
    // deallocate it on exception.
    iterator _M_insert_multi_node(__node_type *__hint, __hash_code __code,
                                  __node_type *__n);
    template <typename... _Args>
    std::pair<iterator, bool> _M_emplace(std::true_type, _Args &&...__args);
