  typename _Rb_tree<_Key, _Val, _KeyOfValue, _Compare, _Alloc>::iterator
  _Rb_tree<_Key, _Val, _KeyOfValue, _Compare, _Alloc>::find(const _Key &__k) {
    iterator __j = _M_lower_bound(_M_begin(), _M_end(), __k);
    return (__j == end() || _M_impl._M_key_compare(__k, _S_key(__j._M_node)))
               ? end()
               : __j;
  }
  template <typename _Key, typename _Val, typename _KeyOfValue,
            typename _Compare, typename _Alloc>
  typename _Rb_tree<_Key, _Val, _KeyOfValue, _Compare, _Alloc>::const_iterator
  _Rb_tree<_Key, _Val, _KeyOfValue, _Compare, _Alloc>::find(const _Key &__k)
      const {
    const_iterator __j = _M_lower_bound(_M_begin(), _M_end(), __k);
    return (__j == end() || _M_impl._M_key_compare(__k, _S_key(__j._M_node)))
               ? end()
               : __j;
  }
  template <typename _Key, typename _Val, typename _KeyOfValue,
            typename _Compare, typename _Alloc>
  typename _Rb_tree<_Key, _Val, _KeyOfValue, _Compare, _Alloc>::size_type
  _Rb_tree<_Key, _Val, _KeyOfValue, _Compare, _Alloc>::count(const _Key &__k)
      const {
    pair<const_iterator, const_iterator> __p = equal_range(__k);
    const size_type __n = std::distance(__p.first, __p.second);
    return __n;
  }
  __attribute__((__pure__)) unsigned int _Rb_tree_black_count(
      const _Rb_tree_node_base *__node,
      const _Rb_tree_node_base *__root) throw();
  template <typename _Key, typename _Val, typename _KeyOfValue,
            typename _Compare, typename _Alloc>
  bool _Rb_tree<_Key, _Val, _KeyOfValue, _Compare, _Alloc>::__rb_verify()
      const {
    if (_M_impl._M_node_count == 0 || begin() == end())
      return _M_impl._M_node_count == 0 && begin() == end() &&
             this->_M_impl._M_header._M_left == _M_end() &&
             this->_M_impl._M_header._M_right == _M_end();
    unsigned int __len = _Rb_tree_black_count(_M_leftmost(), _M_root());
    for (const_iterator __it = begin(); __it != end(); ++__it) {
      _Const_Link_type __x = static_cast<_Const_Link_type>(__it._M_node);
      _Const_Link_type __L = _S_left(__x);
      _Const_Link_type __R = _S_right(__x);
      if (__x->_M_color == _S_red)
        if ((__L && __L->_M_color == _S_red) ||
            (__R && __R->_M_color == _S_red))
          return false;
      if (__L && _M_impl._M_key_compare(_S_key(__x), _S_key(__L)))
        return false;
      if (__R && _M_impl._M_key_compare(_S_key(__R), _S_key(__x)))
        return false;
      if (!__L && !__R && _Rb_tree_black_count(__x, _M_root()) != __len)
        return false;
    }
    if (_M_leftmost() != _Rb_tree_node_base::_S_minimum(_M_root()))
      return false;
    if (_M_rightmost() != _Rb_tree_node_base::_S_maximum(_M_root()))
      return false;
    return true;
  }
