  template <int W2, bool S2> int_base(const range_ref<W2, S2> &x);
  template <int W2, bool S2> int_base(const bit_ref<W2, S2> &x);
  template <int W1, bool S1, int W2, bool S2>
  int_base(const concat_ref<W1, S1, W2, S2> &x);
  int_base &operator=(const int_base &) = default;
  template <int W2, bool S2> int_base &operator=(const int_base<W2, S2> &x) {
    return *this = int_base(x);
  }
  // ── Inspectors ──────────────────────────────────────────────────────
