  int_base &operator-=(int_base x);
  int_base &operator*=(int_base x);
  int_base &operator&=(int_base x);
  int_base &operator|=(int_base x);
  int_base &operator^=(int_base x);
  template <int W2, bool S2> int_base &operator/=(const int_base<W2, S2> &x);
