// Useful routines for initializing flags from the environment.
// In each case, if 'varname' does not exist in the environment
// return defval.  If 'varname' does exist but is not valid
// (e.g., not a number for an int32 flag), abort with an error.
// Otherwise, return the value.  NOTE: for booleans, for true use
// 't' or 'T' or 'true' or '1', for false 'f' or 'F' or 'false' or '0'.
extern __attribute__((visibility("default"))) bool
BoolFromEnv(const char *varname, bool defval);
extern __attribute__((visibility("default"))) int32
Int32FromEnv(const char *varname, int32 defval);
extern __attribute__((visibility("default"))) uint32
Uint32FromEnv(const char *varname, uint32 defval);
