    // Internal constructor functions follow.
    // called by the range constructor to implement [23.1.1]/9
    // _GLIBCXX_RESOLVE_LIB_DEFECTS
    // 438. Ambiguity in the "do the right thing" clause
    template <typename _Integer>
    void _M_initialize_dispatch(_Integer __n, _Integer __x, __true_type) {
      _M_initialize_map(static_cast<size_type>(__n));
      _M_fill_initialize(__x);
    }
    // called by the range constructor to implement [23.1.1]/9
    template <typename _InputIterator>
    void _M_initialize_dispatch(_InputIterator __first, _InputIterator __last,
                                __false_type) {
      _M_range_initialize(__first, __last, std::__iterator_category(__first));
    }
    // called by the second initialize_dispatch above
    //@{
    /**
     *  @brief Fills the deque with whatever is in [first,last).
     *  @param  __first  An input iterator.
     *  @param  __last  An input iterator.
     *  @return   Nothing.
     *
     *  If the iterators are actually forward iterators (or better), then the
     *  memory layout can be done all at once.  Else we move forward using
     *  push_back on each value from the iterator.
     */
    template <typename _InputIterator>
    void _M_range_initialize(_InputIterator __first, _InputIterator __last,
                             std::input_iterator_tag);
    // called by the second initialize_dispatch above
    template <typename _ForwardIterator>
    void _M_range_initialize(_ForwardIterator __first, _ForwardIterator __last,
                             std::forward_iterator_tag);
    //@}
    /**
     *  @brief Fills the %deque with copies of value.
     *  @param  __value  Initial value.
     *  @return   Nothing.
     *  @pre _M_start and _M_finish have already been initialized,
     *  but none of the %deque's elements have yet been constructed.
     *
     *  This function is called only when the user provides an explicit size
     *  (with or without an explicit exemplar value).
     */
    void _M_fill_initialize(const value_type &__value);
    // called by deque(n).
    void _M_default_initialize();
    // Internal assign functions follow.  The *_aux functions do the actual
    // assignment work for the range versions.
    // called by the range assign to implement [23.1.1]/9
    // _GLIBCXX_RESOLVE_LIB_DEFECTS
    // 438. Ambiguity in the "do the right thing" clause
    template <typename _Integer>
    void _M_assign_dispatch(_Integer __n, _Integer __val, __true_type) {
      _M_fill_assign(__n, __val);
    }
    // called by the range assign to implement [23.1.1]/9
    template <typename _InputIterator>
    void _M_assign_dispatch(_InputIterator __first, _InputIterator __last,
                            __false_type) {
      _M_assign_aux(__first, __last, std::__iterator_category(__first));
    }
    // called by the second assign_dispatch above
    template <typename _InputIterator>
    void _M_assign_aux(_InputIterator __first, _InputIterator __last,
                       std::input_iterator_tag);
    // called by the second assign_dispatch above
    template <typename _ForwardIterator>
    void _M_assign_aux(_ForwardIterator __first, _ForwardIterator __last,
                       std::forward_iterator_tag) {
      const size_type __len = std::distance(__first, __last);
      if (__len > size()) {
        _ForwardIterator __mid = __first;
        std::advance(__mid, size());
        std::copy(__first, __mid, begin());
        _M_range_insert_aux(end(), __mid, __last,
                            std::__iterator_category(__first));
      } else
        _M_erase_at_end(std::copy(__first, __last, begin()));
    }
    // Called by assign(n,t), and the range assign when it turns out
    // to be the same thing.
    void _M_fill_assign(size_type __n, const value_type &__val) {
      if (__n > size()) {
        std::fill(begin(), end(), __val);
        _M_fill_insert(end(), __n - size(), __val);
      } else {
        _M_erase_at_end(begin() + difference_type(__n));
        std::fill(begin(), end(), __val);
      }
    }
    //@{
    /// Helper functions for push_* and pop_*.
    template <typename... _Args> void _M_push_back_aux(_Args &&...__args);
    template <typename... _Args> void _M_push_front_aux(_Args &&...__args);
    void _M_pop_back_aux();
    void _M_pop_front_aux();
    //@}
    // Internal insert functions follow.  The *_aux functions do the actual
    // insertion work when all shortcuts fail.
    // called by the range insert to implement [23.1.1]/9
    // _GLIBCXX_RESOLVE_LIB_DEFECTS
    // 438. Ambiguity in the "do the right thing" clause
    template <typename _Integer>
    void _M_insert_dispatch(iterator __pos, _Integer __n, _Integer __x,
                            __true_type) {
      _M_fill_insert(__pos, __n, __x);
    }
    // called by the range insert to implement [23.1.1]/9
    template <typename _InputIterator>
    void _M_insert_dispatch(iterator __pos, _InputIterator __first,
                            _InputIterator __last, __false_type) {
      _M_range_insert_aux(__pos, __first, __last,
                          std::__iterator_category(__first));
    }
    // called by the second insert_dispatch above
    template <typename _InputIterator>
    void _M_range_insert_aux(iterator __pos, _InputIterator __first,
                             _InputIterator __last, std::input_iterator_tag);
    // called by the second insert_dispatch above
    template <typename _ForwardIterator>
    void _M_range_insert_aux(iterator __pos, _ForwardIterator __first,
                             _ForwardIterator __last,
                             std::forward_iterator_tag);
    // Called by insert(p,n,x), and the range insert when it turns out to be
    // the same thing.  Can use fill functions in optimal situations,
    // otherwise passes off to insert_aux(p,n,x).
    void _M_fill_insert(iterator __pos, size_type __n, const value_type &__x);
    // called by insert(p,x)
    template <typename... _Args>
    iterator _M_insert_aux(iterator __pos, _Args &&...__args);
    // called by insert(p,n,x) via fill_insert
    void _M_insert_aux(iterator __pos, size_type __n, const value_type &__x);
    // called by range_insert_aux for forward iterators
    template <typename _ForwardIterator>
    void _M_insert_aux(iterator __pos, _ForwardIterator __first,
                       _ForwardIterator __last, size_type __n);
    // Internal erase functions follow.
    void _M_destroy_data_aux(iterator __first, iterator __last);
    // Called by ~deque().
    // NB: Doesn't deallocate the nodes.
    template <typename _Alloc1>
    void _M_destroy_data(iterator __first, iterator __last, const _Alloc1 &) {
      _M_destroy_data_aux(__first, __last);
    }
    void _M_destroy_data(iterator __first, iterator __last,
                         const std::allocator<_Tp> &) {
      if (!__has_trivial_destructor(value_type))
        _M_destroy_data_aux(__first, __last);
    }
    // Called by erase(q1, q2).
    void _M_erase_at_begin(iterator __pos) {
      _M_destroy_data(begin(), __pos, _M_get_Tp_allocator());
      _M_destroy_nodes(this->_M_impl._M_start._M_node, __pos._M_node);
      this->_M_impl._M_start = __pos;
    }
    // Called by erase(q1, q2), resize(), clear(), _M_assign_aux,
    // _M_fill_assign, operator=.
    void _M_erase_at_end(iterator __pos) {
      _M_destroy_data(__pos, end(), _M_get_Tp_allocator());
      _M_destroy_nodes(__pos._M_node + 1, this->_M_impl._M_finish._M_node + 1);
      this->_M_impl._M_finish = __pos;
    }
    iterator _M_erase(iterator __pos);
    iterator _M_erase(iterator __first, iterator __last);
    // Called by resize(sz).
    void _M_default_append(size_type __n);
    bool _M_shrink_to_fit();
    //@{
    /// Memory-handling helpers for the previous internal insert functions.
    iterator _M_reserve_elements_at_front(size_type __n) {
      const size_type __vacancies =
          this->_M_impl._M_start._M_cur - this->_M_impl._M_start._M_first;
      if (__n > __vacancies)
        _M_new_elements_at_front(__n - __vacancies);
      return this->_M_impl._M_start - difference_type(__n);
    }
    iterator _M_reserve_elements_at_back(size_type __n) {
      const size_type __vacancies =
          (this->_M_impl._M_finish._M_last - this->_M_impl._M_finish._M_cur) -
          1;
      if (__n > __vacancies)
        _M_new_elements_at_back(__n - __vacancies);
      return this->_M_impl._M_finish + difference_type(__n);
    }
    void _M_new_elements_at_front(size_type __new_elements);
    void _M_new_elements_at_back(size_type __new_elements);
    //@}
    //@{
    /**
     *  @brief Memory-handling helpers for the major %map.
     *
     *  Makes sure the _M_map has space for new nodes.  Does not
     *  actually add the nodes.  Can invalidate _M_map pointers.
     *  (And consequently, %deque iterators.)
     */
    void _M_reserve_map_at_back(size_type __nodes_to_add = 1) {
      if (__nodes_to_add + 1 >
          this->_M_impl._M_map_size -
              (this->_M_impl._M_finish._M_node - this->_M_impl._M_map))
        _M_reallocate_map(__nodes_to_add, false);
    }
    void _M_reserve_map_at_front(size_type __nodes_to_add = 1) {
      if (__nodes_to_add >
          size_type(this->_M_impl._M_start._M_node - this->_M_impl._M_map))
        _M_reallocate_map(__nodes_to_add, true);
    }
    void _M_reallocate_map(size_type __nodes_to_add, bool __add_at_front);
