// The accessor names and `BufferAccess` share the kernel's view: a
// `read_only_mmap` is read by the kernel, so the host has to load it.
template <typename T> struct accessor<mmap<T>, placeholder_mmap<T>> {
  static mmap<T> access(placeholder_mmap<T> arg, bool) { return arg; }
  static void access(frt::Instance &instance, int &idx,
                     placeholder_mmap<T> arg) {
    instance.SetBufferArg(idx++, arg.get(), arg.size() * sizeof(T),
                          BufferAccess::PlaceHolder);
  }
};
template <typename T, uint64_t S>
struct accessor<mmaps<T, S>, placeholder_mmaps<T, S>> {
  static void access(frt::Instance &instance, int &idx,
                     placeholder_mmaps<T, S> arg) {
    for (uint64_t i = 0; i < S; ++i) {
      instance.SetBufferArg(idx++, arg[i].get(), arg[i].size() * sizeof(T),
                            BufferAccess::PlaceHolder);
    }
  }
};
template <typename T, int chan_count, int64_t chan_size>
struct accessor<hmap<T, chan_count, chan_size>, placeholder_mmap<T>> {
  static void access(frt::Instance &instance, int &idx,
                     placeholder_mmap<T> arg) {
    for (int i = 0; i < chan_count; ++i) {
      instance.SetBufferArg(idx++, &arg[i * chan_size], chan_size * sizeof(T),
                            BufferAccess::PlaceHolder);
    }
  }
};
