// CEIL_DIVISION(X, Y) = ceil(x/y).
// ROUND_TO_NEXT_MULTIPLE(X, Y) rounds X up to the nearest multiple of Y.
const int IWIDTH = 128;
const int INPUT_DIM = 16;
const int TOP = 10;
// Datapacking compute's output & sort's input
/***************************************************************/
// L2I = Local to Interface
const int L2I_FACTOR_W = ((IWIDTH - 1) / (INPUT_DIM * (32)) + 1);
// D2L = Data_Type to Local
const int D2L_FACTOR_W = (((32) - 1) / 32 + 1);
// D2I = Data_Type to Interface
const int D2I_FACTOR_W = ((IWIDTH - 1) / (INPUT_DIM * 32) + 1);
// I2D = Interface to Data_type
const int I2D_FACTOR_W = (((INPUT_DIM * 32) - 1) / IWIDTH + 1);
// Round up to the nearest multiple, because otherwise some logic breaks
// (incorrect sizes => bad logic in edgecases) We partition the input points, so
// each PE gets it's own partition, to maximize parallelization.
const int PARTITION_LEN_IN_I =
    ((((((((131072) - 1) / (1) + 1) - 1) / ((1) * D2I_FACTOR_W) + 1) *
       ((1) * D2I_FACTOR_W)) *
      32 / 8 * INPUT_DIM) /
     (IWIDTH / 8));
const int PARTITION_LEN_IN_D =
    ((((((((131072) - 1) / (1) + 1) - 1) / ((1) * D2I_FACTOR_W) + 1) *
       ((1) * D2I_FACTOR_W)) *
      32 / 8 * INPUT_DIM) /
     (INPUT_DIM * 32 / 8));
const int PARTITION_LEN_IN_L =
    ((((((((131072) - 1) / (1) + 1) - 1) / ((1) * D2I_FACTOR_W) + 1) *
       ((1) * D2I_FACTOR_W)) *
      32 / 8 * INPUT_DIM) /
     (INPUT_DIM * (32) / 8));
// const int SWIDTH = DATA_TYPE_TOTAL_SZ;
// typedef ap_axiu<SWIDTH, 0, 0, 0> pkt;
// typedef ap_axiu<32, 0, 0, 0>    id_pkt;
// #define STREAM_WIDTH ap_uint<SWIDTH>
const int NUM_FEATURES_PER_READ = (IWIDTH / 32);
const int QUERY_FEATURE_RESERVE = (128);
/*************************************************/
/******************** LOADS: *********************/
/*************************************************/
void load_KNN(int debug_PE_ID, tapa::async_mmap<ap_uint<IWIDTH>> &searchSpace,
              tapa::ostream<ap_uint<IWIDTH>> &load_to_compute_stream) {
#pragma HLS INLINE OFF
  ap_uint<IWIDTH> loaded_value = 0;
LOAD_QUERY:
  for (int i_req = 0, i_resp = 0;
       i_resp < (INPUT_DIM - 1) / NUM_FEATURES_PER_READ + 1;) {
#pragma HLS loop_tripcount min = ((INPUT_DIM - 1) / NUM_FEATURES_PER_READ + 1) \
    max = ((INPUT_DIM - 1) / NUM_FEATURES_PER_READ + 1)
#pragma HLS pipeline II = 1
    // Think of addr as an array index.
    int addr = i_req;
    if (i_req < (INPUT_DIM - 1) / NUM_FEATURES_PER_READ + 1 &&
        !searchSpace.read_addr.full()) {
      searchSpace.read_addr.write(addr * sizeof(ap_uint<IWIDTH>));
      i_req++;
    }
    if (!searchSpace.read_data.empty()) {
      loaded_value = searchSpace.read_data.read();
      i_resp++;
      // DEBUGGING:
      for (int i = 0; i < NUM_FEATURES_PER_READ; ++i) {
        ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
                 AP_RND, AP_SAT>
            cur_value = 0;
        ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
                 AP_RND, AP_SAT>
            tmp;
        tmp.range(32 - 1, 0) = loaded_value(i * 32 + (32 - 1), i * 32);
        cur_value = *(
            (ap_fixed<32,
                      12 /* NOTE: This includes the sign bit, if applicable.*/,
                      AP_RND, AP_SAT> *)(&tmp));
        if (cur_value < (2047.9999990463257) && debug_PE_ID == 0) {
          ((void)0);
        }
      }
      load_to_compute_stream.write(loaded_value);
    }
  }
LOAD_SEARCHSPACE:
  for (int i_req = 0, i_resp = 0; i_resp < PARTITION_LEN_IN_I;) {
#pragma HLS loop_tripcount min = PARTITION_LEN_IN_I max = PARTITION_LEN_IN_I
#pragma HLS pipeline II = 1
    // Think of addr as an array index.
    int addr = (QUERY_FEATURE_RESERVE / NUM_FEATURES_PER_READ) + i_req;
    if (i_req < PARTITION_LEN_IN_I && !searchSpace.read_addr.full()) {
      searchSpace.read_addr.write(addr * sizeof(ap_uint<IWIDTH>));
      i_req++;
    }
    if (!searchSpace.read_data.empty()) {
      loaded_value = searchSpace.read_data.read();
      i_resp++;
      //// DEBUGGING: Printing the loaded data:
      // #ifndef __SYNTHESIS__
      // for (int i = 0; i < NUM_FEATURES_PER_READ; ++i)
      //{
      //     DATA_TYPE cur_value = 0;
      //     TRANSFER_TYPE tmp;
      //     tmp.range(DATA_TYPE_TOTAL_SZ - 1, 0)
      //         = loaded_value(i*DATA_TYPE_TOTAL_SZ + (DATA_TYPE_TOTAL_SZ - 1),
      //                         i*DATA_TYPE_TOTAL_SZ);
      //     cur_value = *((DATA_TYPE*) (&tmp));
      //     if (cur_value < MAX_DATA_TYPE_VAL && debug_PE_ID == 0)
      //     {
      //         printf("LOAD SEARCHSPACE: value = %f, i_resp = %d\n",
      //         cur_value, i_resp);
      //     }
      // }
      // #endif
      //// DEBUGGING: Printing how many times we write to each stream:
      // #ifndef __SYNTHESIS__
      // if (debug_PE_ID == 0)
      //{
      //     printf("LOAD: Writing to load_to_compute_stream for the %d-th
      //     time\n",
      //             i_resp-1);
      // }
      // #endif
      load_to_compute_stream.write(loaded_value);
    }
  }
}
/*************************************************/
/******************* COMPUTES: *******************/
/*************************************************/
void compute_KNN(
    int debug_pe_idx, int debug_start_idx,
    tapa::istream<ap_uint<IWIDTH>> &load_to_compute_stream,
    tapa::ostream<
        ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
                 AP_RND, AP_SAT>> &compute_to_sort_stream) {
#pragma HLS INLINE OFF
  int DEBUG_load_ctr = 0;
  ap_uint<IWIDTH> cur_data = 0;
  ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/, AP_RND,
           AP_SAT>
      local_Query[INPUT_DIM];
#pragma HLS ARRAY_PARTITION variable = local_Query complete dim = 1
  int DEBUG_write_counters = {};
/***********************************************/
GET_QUERYDATA:
  for (int i = 0; i < ((INPUT_DIM - 1) / NUM_FEATURES_PER_READ + 1); ++i) {
    ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
             AP_RND, AP_SAT>
        tmp = 0;
    int input_dim_idx = i * NUM_FEATURES_PER_READ;
    cur_data = load_to_compute_stream.read();
    for (int j = 0; j < NUM_FEATURES_PER_READ && input_dim_idx < INPUT_DIM;
         ++j, ++input_dim_idx) {
      tmp.range(32 - 1, 0) = cur_data.range(j * 32 + (32 - 1), j * 32);
      local_Query[input_dim_idx] = tmp;
    }
  }
COMPUTE_DATA:
  for (int ii = 0; ii < PARTITION_LEN_IN_D; ++ii) {
    ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
             AP_RND, AP_SAT>
        dist_val_outer = 0;
    for (int jj = 0; jj < I2D_FACTOR_W; ++jj) {
#pragma HLS PIPELINE II = 1
      cur_data = load_to_compute_stream.read();
      ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
               AP_RND, AP_SAT>
          dist_val_inner = 0;
      for (int kk = 0; kk < NUM_FEATURES_PER_READ; ++kk) {
#pragma HLS UNROLL
        int range_idx = kk * 32;
        int querypt_idx = jj * NUM_FEATURES_PER_READ + kk;
        ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
                 AP_RND, AP_SAT>
            sp_dim_item_value;
        sp_dim_item_value.range(32 - 1, 0) =
            cur_data.range(range_idx + (32 - 1), range_idx);
        ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
                 AP_RND, AP_SAT>
            delta =
                ((sp_dim_item_value - local_Query[querypt_idx]) > 0
                     ? static_cast<ap_fixed<32, 12 /* NOTE: This includes the
                                                      sign bit, if applicable.*/
                                            ,
                                            AP_RND, AP_SAT>>(
                           sp_dim_item_value - local_Query[querypt_idx])
                     : static_cast<ap_fixed<32, 12 /* NOTE: This includes the
                                                      sign bit, if applicable.*/
                                            ,
                                            AP_RND, AP_SAT>>(
                           -1 *
                           (sp_dim_item_value - local_Query[querypt_idx])));
        dist_val_inner += delta;
      }
      dist_val_outer += dist_val_inner;
    }
    // #ifndef __SYNTHESIS__
    // if (dist_val_outer < MAX_DATA_TYPE_VAL && ii % 1000 == 0){
    //     printf("KDEBUG: In compute, the %d-th computed value has
    //     dist_val_outer = %f\n",
    //             ii, dist_val_outer.to_float());
    // }
    // #endif
    compute_to_sort_stream.write(dist_val_outer);
  }
}
void para_partial_sort(
    const int PE_idx,
    tapa::istream<
        ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
                 AP_RND, AP_SAT>> &compute_to_sort_stream,
    tapa::ostream<
        ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
                 AP_RND, AP_SAT>> &sort_to_hiermerge_dist_stream,
    tapa::ostream<int> &sort_to_hiermerge_id_stream) {
#pragma HLS INLINE OFF
  ((void)0);
  ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/, AP_RND,
           AP_SAT>
      local_kNearstDist[(TOP + 1)];
#pragma HLS ARRAY_PARTITION variable = local_kNearstDist complete dim = 0
  int local_kNearstId[(TOP + 1)];
#pragma HLS ARRAY_PARTITION variable = local_kNearstId complete dim = 0
  int DEBUG_stream_counters = 0;
  int start_id =
      PE_idx * ((((((131072) - 1) / (1) + 1) - 1) / ((1) * D2I_FACTOR_W) + 1) *
                ((1) * D2I_FACTOR_W));
/*******************************************/
// Initialize all top-K distances to MAX, and their IDs to an invalid value.
INIT_LOOP:
  for (int j = 0; j < TOP + 1; ++j) {
    local_kNearstId[j] = -1;
    local_kNearstDist[j] = (2047.9999990463257);
  }
SORT_LOOP:
  for (int dvalue_idx = 0; dvalue_idx < (PARTITION_LEN_IN_D + TOP);
       ++dvalue_idx) {
#pragma HLS PIPELINE II = I2D_FACTOR_W
    ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
             AP_RND, AP_SAT>
        cur_Dval = 0;
    if (dvalue_idx >= PARTITION_LEN_IN_D) {
      cur_Dval = (2047.9999990463257);
    } else {
      // #ifndef __SYNTHESIS__
      // printf("PPS Unit for PE %d: Reading from compute_to_sort_stream, for
      // the %d-th time\n",
      //         PE_idx,
      //         DEBUG_stream_counters++);
      // #endif
      cur_Dval = compute_to_sort_stream.read();
    }
    local_kNearstDist[0] = cur_Dval;
    local_kNearstId[0] = start_id + dvalue_idx;
    // #ifndef __SYNTHESIS__
    // printf("SORT: Current ID = %d, cur_Dval = %f\n", start_id + dvalue_idx,
    // cur_Dval); printf("SORT: Best ID = %d, Best Dval = %f\n",
    // local_kNearstId[TOP], local_kNearstDist[TOP]); #endif compare and swap
    // odd
    for (int ii = 1; ii < TOP; ii += 2) {
#pragma HLS UNROLL
#pragma HLS DEPENDENCE variable = local_kNearstDist inter false
#pragma HLS DEPENDENCE variable = local_kNearstId inter false
      if (local_kNearstDist[ii] < local_kNearstDist[ii + 1]) {
        do {
          ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
                   AP_RND, AP_SAT>
              _tmpdist_a = *(&local_kNearstDist[ii]);
          ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
                   AP_RND, AP_SAT>
              _tmpdist_b = *(&local_kNearstDist[ii + 1]);
          *(&local_kNearstDist[ii + 1]) = _tmpdist_a;
          *(&local_kNearstDist[ii]) = _tmpdist_b;
          int _tmpid_x = *(&local_kNearstId[ii]);
          int _tmpid_y = *(&local_kNearstId[ii + 1]);
          *(&local_kNearstId[ii]) = _tmpid_y;
          *(&local_kNearstId[ii + 1]) = _tmpid_x;
        } while (0);
      }
    }
    // compare and swap even
    for (int ii = 1; ii < TOP + 1; ii += 2) {
#pragma HLS UNROLL
#pragma HLS DEPENDENCE variable = local_kNearstDist inter false
#pragma HLS DEPENDENCE variable = local_kNearstId inter false
      if (local_kNearstDist[ii] > local_kNearstDist[ii - 1]) {
        do {
          ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
                   AP_RND, AP_SAT>
              _tmpdist_a = *(&local_kNearstDist[ii]);
          ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
                   AP_RND, AP_SAT>
              _tmpdist_b = *(&local_kNearstDist[ii - 1]);
          *(&local_kNearstDist[ii - 1]) = _tmpdist_a;
          *(&local_kNearstDist[ii]) = _tmpdist_b;
          int _tmpid_x = *(&local_kNearstId[ii]);
          int _tmpid_y = *(&local_kNearstId[ii - 1]);
          *(&local_kNearstId[ii]) = _tmpid_y;
          *(&local_kNearstId[ii - 1]) = _tmpid_x;
        } while (0);
      }
    }
  }
// Write data out
OUTPUT_LOOP:
  for (int j = TOP; j > 0; --j) {
#pragma HLS PIPELINE II = 1
    sort_to_hiermerge_dist_stream.write(local_kNearstDist[j]);
    sort_to_hiermerge_id_stream.write(local_kNearstId[j]);
  }
  for (int j = 0; j < TOP + 1; ++j) {
    ((void)0);
    ((void)0);
    ((void)0);
  }
REINITIALIZATION_LOOP:
  for (int j = 0; j < TOP + 1; ++j) {
#pragma HLS UNROLL
    // Reset the kNearst values so we can run the next iteration.
    local_kNearstId[j] = -1;
    local_kNearstDist[j] = (2047.9999990463257);
  }
}
void krnl_singlePE_Write_Outputs(
    tapa::istream<
        ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
                 AP_RND, AP_SAT>> &in_dist0,
    tapa::istream<int> &in_id0, tapa::async_mmap<ap_uint<32>> &output_knn) {
  ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/, AP_RND,
           AP_SAT>
      cur_dist;
  int cur_id;
  int i_req_output = 2 * TOP - 1;
  int i_resp_output = 2 * TOP - 1;
  for (int i = 0; i < TOP; ++i) {
#pragma HLS pipeline II = 1
    cur_dist = in_dist0.read();
    cur_id = in_id0.read();
    ap_uint<32> outval = 0;
    if (i_req_output < 2 * TOP && i_req_output >= 0 &&
        !output_knn.write_addr.full() && !output_knn.write_data.full()) {
      outval.range(32 - 1, 0) = cur_dist.range(32 - 1, 0);
      output_knn.write_addr.write(i_req_output * sizeof(ap_uint<32>));
      output_knn.write_data.write(outval);
      --i_req_output;
    }
    if (!output_knn.write_resp.empty()) {
      i_resp_output += (unsigned int)(output_knn.write_resp.read()) + 1;
    }
    if (i_req_output < 2 * TOP && i_req_output >= 0 &&
        !output_knn.write_addr.full() && !output_knn.write_data.full()) {
      outval = *(ap_uint<32> *)&cur_id;
      output_knn.write_addr.write(i_req_output * sizeof(ap_uint<32>));
      output_knn.write_data.write(outval);
      --i_req_output;
    }
    if (!output_knn.write_resp.empty()) {
      i_resp_output += (unsigned int)(output_knn.write_resp.read()) + 1;
    }
  }
}
void Knn(tapa::async_mmap<ap_uint<IWIDTH>> &in_0,
         tapa::async_mmap<ap_uint<32>> &final_out) {
  // Streams, for the global merge:
  tapa::stream<
      ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
               AP_RND, AP_SAT>,
      TOP>
      L0_out_dist_0;
  tapa::stream<int, TOP> L0_out_id_0;
  // Streams, for load->compute->sort:
  tapa::stream<ap_uint<IWIDTH>, 2> load_to_compute_stream_0;
  tapa::stream<
      ap_fixed<32, 12 /* NOTE: This includes the sign bit, if applicable.*/,
               AP_RND, AP_SAT>,
      2>
      compute_to_sort_stream_0;
  tapa::task()
      .invoke(load_KNN, 0, in_0, load_to_compute_stream_0)
      .invoke(compute_KNN, 0,
              ((((((131072) - 1) / (1) + 1) - 1) / ((1) * D2I_FACTOR_W) + 1) *
               ((1) * D2I_FACTOR_W)) *
                  0,
              load_to_compute_stream_0, compute_to_sort_stream_0)
      .invoke(para_partial_sort, 0, compute_to_sort_stream_0, L0_out_dist_0,
              L0_out_id_0)
      ////////// MERGING LOGIC
      // INTER-PE HIERMERGE:
      .invoke(krnl_singlePE_Write_Outputs, L0_out_dist_0, L0_out_id_0,
              final_out);
}
